def transform(grid):
    base = [row[::-1] for row in grid[::-1]]
    out = []
    n = len(grid)
    for tr in range(3):
        for r in range(n):
            row = []
            part = base[n-1-r] if tr % 2 else base[r]
            for tc in range(3):
                row.extend(part[::-1] if tc % 2 else part)
            out.append(row)
    return out
